// -------------------------------------------------
// Extract keyword from task name for epic matching
// and normalize all task data for downstream nodes.
// -------------------------------------------------

const task = $input.first().json;

// --- Keyword extraction ---
// Strategy: take the text before the first colon, dash, or em-dash.
// Fall back to the first two words if no delimiter found.
const taskName = task.content || '';
const parts = taskName.split(/[:\-\u2013\u2014]/);
const firstPart = parts[0].trim();
const words = firstPart.split(/\s+/);
const keyword = words.slice(0, 2).join(' ');

// --- Priority mapping (Todoist → Notion) ---
// Todoist: 4=p1 (most urgent), 1=p4 (least urgent)
const priorityMap = { 4: 'Urgent', 3: 'High', 2: 'Medium', 1: 'Low' };

return {
  keyword: keyword || taskName,
  taskId: String(task.id),
  taskName: taskName,
  taskDescription: task.description || '',
  taskPriority: priorityMap[task.priority] || 'Medium',
  taskUrl: task.url || '',
  todoistPriority: task.priority
};
